// Small progressive-enhancement layer for the portfolio.
document.addEventListener('DOMContentLoaded', function() {
    const menuButton = document.getElementById('menu-btn') || document.querySelector('[id*="menu"]');
    const mobileMenu = document.getElementById('mobile-menu');
    
    if (menuButton && mobileMenu) {
        menuButton.addEventListener('click', function() {
            mobileMenu.classList.toggle('open');
        });
        
        // Close menu when clicking outside
        document.addEventListener('click', function(event) {
            if (!event.target.closest('#navbar')) {
                mobileMenu.classList.remove('open');
            }
        });
    }
    
    // Smooth scroll behavior
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function(e) {
            e.preventDefault();
            const target = document.querySelector(this.getAttribute('href'));
            if (target) {
                target.scrollIntoView({ behavior: 'smooth' });
            }
        });
    });
    
    // Lazy load images
    if ('IntersectionObserver' in window) {
        const imageObserver = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const img = entry.target;
                    img.src = img.dataset.src;
                    img.classList.add('loaded');
                    observer.unobserve(img);
                }
            });
        });
        
        document.querySelectorAll('img[data-src]').forEach(img => {
            imageObserver.observe(img);
        });
    }
    
    // Skill bar animation on scroll
    const skillBars = document.querySelectorAll('.skill-bar');
    if (skillBars.length > 0 && 'IntersectionObserver' in window) {
        const skillObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.style.width = entry.target.dataset.width || '80%';
                    skillObserver.unobserve(entry.target);
                }
            });
        });
        
        skillBars.forEach(bar => skillObserver.observe(bar));
    }

    initPortfolioMotion();
});

function initPortfolioMotion() {
    if (!window.gsap || !window.ScrollTrigger) return;

    gsap.registerPlugin(ScrollTrigger);
    if (window.Observer) gsap.registerPlugin(Observer);
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduceMotion) return;

    const sections = gsap.utils.toArray('section');
    const cards = gsap.utils.toArray('section .rounded-lg, section .rounded-xl');
    const rules = gsap.utils.toArray('section .w-20');
    const icons = gsap.utils.toArray('i.fas:not(.fa-spinner), i.fab, .social-x-icon');
    const stats = gsap.utils.toArray('.stat-value');

    gsap.from('#navbar', { y: -80, opacity: 0, duration: 0.9, ease: 'power3.out' });
    gsap.from('#home h1, #home h2, #home p, #home .flex', {
        y: 28, opacity: 0, duration: 0.8, stagger: 0.1, delay: 0.25, ease: 'power3.out'
    });
    gsap.set('#home img, #hero-portrait', { autoAlpha: 1 });

    gsap.timeline({ repeat: -1, yoyo: true, defaults: { ease: 'sine.inOut' } })
        .to('#home h1', { y: -6, duration: 2.4 })
        .to('#home h1 span', { textShadow: '0 0 18px rgba(255, 160, 0, 0.45)', duration: 1.2 }, 0.5);

    gsap.timeline({ repeat: -1, yoyo: true, defaults: { ease: 'sine.inOut' } })
        .to('#hero-portrait', { y: -10, rotate: 1.5, duration: 2.8 })
        .to('#home img', { scale: 1.035, duration: 2.8 }, 0);

    stats.forEach((stat) => {
        const original = stat.textContent.trim();
        const match = original.match(/^(\d+)(.*)$/);
        if (!match) return;
        const counter = { value: 0 };
        stat.textContent = `0${match[2]}`;
        gsap.to(counter, {
            value: Number(match[1]), duration: 1.6, ease: 'power2.out',
            snap: { value: 1 },
            onUpdate: () => { stat.textContent = `${counter.value}${match[2]}`; },
            scrollTrigger: { trigger: stat, start: 'top 88%', once: true }
        });
        gsap.from(stat, {
            scale: 0.7, y: 16, duration: 0.7, ease: 'back.out(2)',
            scrollTrigger: { trigger: stat, start: 'top 88%', once: true }
        });
    });

    icons.forEach((icon, index) => {
        const section = icon.closest('section') || icon;
        gsap.from(icon, {
            y: index % 2 ? 10 : -10, rotate: index % 2 ? -12 : 12, duration: 0.7,
            ease: 'back.out(2)', scrollTrigger: { trigger: section, start: 'top 86%', once: true }
        });
        const scale = gsap.quickTo(icon, 'scale', { duration: 0.25, ease: 'power2.out' });
        icon.addEventListener('mouseenter', () => { scale(1.18); gsap.to(icon, { rotate: '+=12', duration: 0.25 }); });
        icon.addEventListener('mouseleave', () => { scale(1); gsap.to(icon, { rotate: 0, duration: 0.35, ease: 'back.out(1.7)' }); });
    });

    sections.slice(1).forEach((section, index) => {
        const heading = section.querySelector('h2');
        if (heading) {
            gsap.from(heading, {
                y: 35, duration: 0.8, ease: index % 2 ? 'elastic.out(1, 0.65)' : 'back.out(1.4)',
                scrollTrigger: { trigger: section, start: 'top 78%', once: true }
            });
        }
        const content = section.querySelectorAll('p, li, h3, h4, label');
        gsap.from(content, {
            y: 18, duration: 0.65, stagger: 0.045, delay: 0.12,
            ease: index % 3 === 0 ? 'power4.out' : 'circ.out',
            scrollTrigger: { trigger: section, start: 'top 74%', once: true }
        });
    });

    cards.forEach((card, index) => {
        gsap.from(card, {
            y: 42, rotate: index % 2 ? 1.5 : -1.5, duration: 0.75,
            ease: index % 3 === 0 ? 'back.out(1.5)' : 'power3.out',
            scrollTrigger: { trigger: card, start: 'top 88%', once: true }
        });
    });

    gsap.utils.toArray('h1, h2, h3').forEach((heading, index) => {
        const text = heading.textContent.trim();
        if (!text || heading.children.length || text.length > 42) return;
        heading.setAttribute('aria-label', text);
        heading.innerHTML = text.split('').map((character) =>
            `<span aria-hidden="true" style="display:inline-block">${character === ' ' ? '&nbsp;' : character}</span>`
        ).join('');
        gsap.from(heading.children, {
            y: index % 2 ? 18 : -18, rotateX: index % 2 ? -70 : 70,
            duration: 0.65, stagger: 0.025, ease: 'back.out(1.7)',
            scrollTrigger: { trigger: heading, start: 'top 84%', once: true }
        });
    });

    rules.forEach((rule) => gsap.from(rule, {
        scaleX: 0, transformOrigin: 'left center', duration: 1.1, ease: 'power3.inOut',
        scrollTrigger: { trigger: rule, start: 'top 82%', once: true }
    }));

    gsap.to('.portfolio-marquee', {
        xPercent: -25, ease: 'none',
        scrollTrigger: { trigger: '.portfolio-marquee', start: 'top bottom', end: 'bottom top', scrub: 1 }
    });

    gsap.to('#scroll-progress', {
        scaleX: 1, transformOrigin: 'left center', ease: 'none',
        scrollTrigger: { start: 'top top', end: 'max', scrub: 0.25 }
    });

    cards.forEach((card) => {
        const lift = gsap.quickTo(card, 'y', { duration: 0.35, ease: 'back.out(2)' });
        card.addEventListener('mouseenter', () => { lift(-8); gsap.to(card, { rotate: 0, duration: 0.35 }); });
        card.addEventListener('mouseleave', () => { lift(0); gsap.to(card, { rotate: 0, duration: 0.45, ease: 'elastic.out(1, 0.5)' }); });
    });

    if (window.Observer) {
        Observer.create({ target: window, type: 'pointer', onMove: (event) => {
            gsap.to('#hero-portrait', { x: event.x * 0.008, duration: 0.8, ease: 'power2.out', overwrite: true });
        } });
    }
}

// Dark mode toggle
function toggleDarkMode() {
    const html = document.documentElement;
    const isDark = html.classList.contains('dark');
    
    if (isDark) {
        html.classList.remove('dark');
        localStorage.setItem('theme', 'light');
    } else {
        html.classList.add('dark');
        localStorage.setItem('theme', 'dark');
    }
}

// Load saved theme preference
window.addEventListener('DOMContentLoaded', () => {
    const savedTheme = localStorage.getItem('theme');
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    const isDark = savedTheme === 'dark' || (savedTheme === null && prefersDark);
    
    if (isDark) {
        document.documentElement.classList.add('dark');
    }
});
